package ca.yorku.eecs3311.coursepilot.application.service;
import ca.yorku.eecs3311.coursepilot.application.dto.*; import ca.yorku.eecs3311.coursepilot.domain.model.*; import ca.yorku.eecs3311.coursepilot.domain.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class LearningHistoryService {private final FlashcardReviewRepository reviews;private final QuizAttemptRepository attempts;private final StudyPlanRepository plans;public LearningHistoryService(FlashcardReviewRepository r,QuizAttemptRepository a,StudyPlanRepository p){reviews=r;attempts=a;plans=p;}
 @Transactional(readOnly=true) public List<HistoryEvent> list(Long courseId){List<HistoryEvent> out=new ArrayList<>();for(var r:reviews.findByCourseIdOrderByIdAsc(courseId))out.add(new HistoryEvent(r.getReviewedAt(),"FLASHCARD_REVIEW","Flashcard reviewed",r.getRating().name()+" · "+r.getFlashcard().getQuestion()));for(var a:attempts.findByCourseId(courseId))out.add(new HistoryEvent(a.getCompletedAt()==null?a.getStartedAt():a.getCompletedAt(),"QUIZ_ATTEMPT","Quiz completed",a.getCorrectCount()+" / "+a.getTotalCount()+" correct · "+a.getQuiz().getTitle()));for(var p:plans.findByCourseId(courseId))out.add(new HistoryEvent(p.getCreatedAt(),"STUDY_PLAN","Study plan created",p.getStrategy()+" · "+p.getItems().size()+" activities"));return out.stream().sorted(Comparator.comparing(HistoryEvent::occurredAt,Comparator.nullsLast(Comparator.reverseOrder()))).limit(100).toList();}
 public List<HistoryEvent> recent(Long courseId,int limit){return list(courseId).stream().limit(Math.max(1,Math.min(limit,100))).toList();}}
